-- Phong Than "Lenh Bai Chien Truong Thuong Chu" (magicscript 61471, task 2671; 2026-10-04, agent vtcc). Permanent, never consumed
-- (KItemList::ExecuteScript only calls main; this script never removes the item). Generated by
-- scratchpad\vtcc\gen.py - edit the generator, not this file. Doc: docs\features\lenh-bai-van-tien-thuong-chu-phong-than-20261004.md
-- Thuong Chu battlefield = VNG Vien Co chien truong (Mission 5, map 71 = runtime 1071), rebuilt by agent vienco as a
-- solo PvE war (both armies are NPCs, camp 1 Thuong / camp 2 Chu), library vc_lib.lua, minute tick ext\vienco.lua.
-- Right click: pick Thuong or Chu. Open round with >= 5 minutes left: join it at once (PTVC_Enter, as the Chien Su).
-- Closed: this script opens a 45-minute round itself on the shared GlobalValues (state, key, scores, end minute,
-- slots = PTVC_OpenRound minus the armies), sets GlobalValue 2670 (PTVC_GV_REQ) = round key and enters the player
-- in his base camp; the next minute tick of ext\vienco.lua adopts the round as a forced round (PTVC_FORCE_END)
-- and spawns both armies, scores, settles and rewards it like any other round.
-- No VNG limits: no schedule, no level, no PK limit, no fee; the VNG one-result-per-day rule of Vi Quoc Lap Cong
-- is lifted once per token entry (reward = the VNG one, never multiplied). A player still in the current round
-- (left the map) goes back for free, without cooldown.
-- Cooldown: task 2671 = server clock (seconds since 2000-01-01) of the last successful entry, 3600 s.
-- Lua 4 / engine: no top-level dofile (the library is loaded at call time, cwd = Server), menus <= 7 rows.

PTTC_ITEM = 61471
PTTC_TASK = 2671
PTTC_CD = 3600
PTTC_GV_REQ = 2670             -- read by PTVC_Schedule (ext\vienco.lua): adopt this round key as a forced round
PTTC_LEN = 45                  -- minutes, = PTVC_LEN of ext\vienco.lua
PTTC_MINLEFT = 5

function PTTC_Load()
	if not PTVC_Enter then dofile("script\\phongthan\\vienco\\vc_lib.lua") end
end

-- map id of the player if the token may be used here (field maps, cities), else nil: never from inside
-- Van Tien tran (1079-1082), the battlefield (1071), events, instances or Thien Lao (1060)
function PTTC_SrcOk()
	local m = GetWorldPos()
	if not m then return nil end
	if m >= 1001 and m <= 1057 then return m end
	if m == 1065 or (m >= 1074 and m <= 1078) then return m end
	return nil
end

-- seconds since 2000-01-01 on the server clock (date()); fits a task value until 2068
function PTTC_Now()
	local y = tonumber(date("%Y")) or 2000
	local j = tonumber(date("%j")) or 1
	local h = tonumber(date("%H")) or 0
	local mi = tonumber(date("%M")) or 0
	local s = tonumber(date("%S")) or 0
	local d = (y - 2000) * 365 + floor((y - 1997) / 4) + j - 1
	return d * 86400 + h * 3600 + mi * 60 + s
end

-- seconds left of the 1-hour cooldown (0 = ready). A clock set back makes the token ready again.
function PTTC_Left()
	local last = GetTask(PTTC_TASK)
	if last <= 0 then return 0 end
	local left = last + PTTC_CD - PTTC_Now()
	if left <= 0 or left > PTTC_CD then return 0 end
	return left
end

function PTTC_LeftText(left)
	return floor(left / 60) .. " ph\243t " .. mod(left, 60) .. " gi\169y"
end

function PTTC_Say(title, o)
	local n = getn(o)
	local t = { title, n }
	local k = 1
	while k <= n do t[k + 2] = o[k] k = k + 1 end
	call(Say, t)
end

-- close row of every menu (the name the engine dialogs and the simulators expect)
function no()
end

function PTTC_Blocked()
	Say("<color=yellow>L\214nh B\181i Chi\213n Tr\173\234ng Th\173\172ng Chu<color>: kh\171ng d\239ng \174\173\238c \235 b\182n \174\229 n\181y (trong chi\213n tr\173\234ng, V\185n Ti\170n tr\203n, s\249 ki\214n, ph\227 b\182n, Thi\170n Lao). H\183y ra b\182n \174\229 ngo\181i ho\198c v\210 th\181nh tr\173\237c.", 1, "\167\227ng/no")
end

function PTTC_Main()
	PTTC_Load()
	PTVC_Lazy()
	local st = PTVC_StatusText()
	if PTVC_InRound() then
		local s = GetTask(PTVC_T_SIDE)
		Say("<color=yellow>L\214nh B\181i Chi\213n Tr\173\234ng Th\173\172ng Chu<color>: ng\173\172i v\201n \174ang trong tr\203n n\181y. " .. st, 2, "Tr\235 l\185i chi\213n tr\173\234ng (" .. PTVC_SIDENAME[s] .. ", kh\171ng t\221nh l\173\238t)/PTTC_Back", "\167\227ng/no")
		return
	end
	local left = PTTC_Left()
	if left > 0 then
		Say("<color=yellow>L\214nh B\181i Chi\213n Tr\173\234ng Th\173\172ng Chu<color>: l\214nh b\181i \174ang h\229i, c\223n <color=red>" .. PTTC_LeftText(left) .. "<color> n\247a m\237i d\239ng l\185i \174\173\238c. " .. st, 1, "\167\227ng/no")
		return
	end
	if PTVC_Open() and PTVC_MinLeft() < PTTC_MINLEFT then
		Say("<color=yellow>L\214nh B\181i Chi\213n Tr\173\234ng Th\173\172ng Chu<color>: tr\203n hi\214n t\185i ch\216 c\223n " .. PTVC_MinLeft() .. " ph\243t. H\183y d\239ng l\185i l\214nh b\181i khi tr\203n k\213t th\243c \174\211 m\235 tr\203n m\237i (ch\173a t\221nh l\173\238t).", 1, "\167\227ng/no")
		return
	end
	local t = "<color=yellow>L\214nh B\181i Chi\213n Tr\173\234ng Th\173\172ng Chu<color>: v\181o chi\213n tr\173\234ng Th\173\172ng Chu ngay: kh\171ng c\199n \174\238i gi\234, kh\171ng ph\221, kh\171ng gi\237i h\185n c\202p. Chi\213n tr\173\234ng \174ang \174\227ng s\207 khai chi\213n ngay (45 ph\243t), qu\169n NPC hai phe d\181n tr\203n trong v\223ng 1 ph\243t. M\231i l\199n d\239ng h\229i 60 ph\243t. "
	PTTC_Say(t .. st, { "V\181o phe Th\173\172ng (V\168n Tr\228ng)/PTTC_Shang", "V\181o phe Chu (Kh\173\172ng Th\173\238ng)/PTTC_Zhou", "\167\227ng/no" })
end

-- open a round now on the shared GlobalValues (PTVC_OpenRound of ext\vienco.lua without the armies, which the
-- servertimer state spawns when it adopts the round through PTTC_GV_REQ)
function PTTC_OpenRound()
	local h = tonumber(date("%H")) or 0
	local m = tonumber(date("%M")) or 0
	local key = tonumber(date("%m%d%H%M")) or 0
	SetGlobalValue(PTVC_GV_ROUND, key)
	SetGlobalValue(PTVC_GV_SCORE + 1, 0)
	SetGlobalValue(PTVC_GV_SCORE + 2, 0)
	SetGlobalValue(PTVC_GV_END, mod(h * 60 + m + PTTC_LEN, 1440))
	local i = 1
	while i <= PTVC_SLOTS do
		SetGlobalValue(PTVC_GV_SLOT + i, 0)
		i = i + 1
	end
	SetGlobalValue(PTVC_GV_STATE, 2)
	SetGlobalValue(PTTC_GV_REQ, key)
	AddGlobalCountNews("<color=green>Chi\213n tr\173\234ng Th\173\172ng Chu<color> khai chi\213n! <color=yellow>" .. (GetName() or "") .. "<color> d\239ng L\214nh B\181i Chi\213n Tr\173\234ng Th\173\172ng Chu m\235 tr\203n m\237i (45 ph\243t). Anh h\239ng h\183y \174\213n <color=green>Phong Th\199n \167\181i<color> g\198p Vi\212n C\230 Chi\213n S\248.", 2)
	return key
end

-- VNG allows one Vi Quoc Lap Cong result per day (task PTVC_T_DAY = day of the last result, VNG task 410); a token
-- entry may take one more objective, rewarded like any VNG one (never multiplied)
function PTTC_DailyFree()
	if GetTask(PTVC_T_DAY) ~= PTVC_Today() then return 0 end
	SetTask(PTVC_T_DAY, 0)
	Msg2Player("L\214nh B\181i Chi\213n Tr\173\234ng Th\173\172ng Chu: h\171m nay \174\183 nh\203n 'V\222 Qu\232c L\203p C\171ng', l\214nh b\181i cho nh\203n th\170m 1 l\199n trong tr\203n n\181y (th\173\235ng nh\173 VNG).")
	return 1
end

function PTTC_MapOk()
	local sw = SubWorldID2Idx(PTVC_MAP)
	if sw and sw >= 0 then return 1 end
	Msg2Player("B\182n \174\229 chi\213n tr\173\234ng Th\173\172ng Chu ch\173a \174\173\238c n\185p tr\170n m\184y ch\241.")
	return nil
end

function PTTC_Go(side)
	PTTC_Load()
	PTVC_Lazy()
	if not PTTC_SrcOk() then PTTC_Blocked() return end
	if PTVC_InRound() then PTTC_Back() return end
	if PTTC_Left() > 0 then PTTC_Main() return end
	if not PTTC_MapOk() then return end
	local opened = 0
	if PTVC_Open() then
		if PTVC_MinLeft() < PTTC_MINLEFT then PTTC_Main() return end
	else
		PTTC_OpenRound()
		opened = 1
	end
	if not PTVC_Enter(side) then
		Msg2Player("Chi\213n tr\173\234ng \174\183 \174\241 ng\173\234i, h\183y \174\238i tr\203n sau.")
		return
	end
	SetTask(PTTC_TASK, PTTC_Now())
	PTTC_DailyFree()
	if opened == 1 then
		Msg2Player("Chi\213n tr\173\234ng v\245a khai chi\213n: qu\169n hai phe s\207 d\181n tr\203n trong v\223ng 1 ph\243t. G\198p ch\241 t\173\237ng nh\203n 'V\222 Qu\232c L\203p C\171ng' r\229i ch\228n Xu\202t tr\203n.")
	end
	Msg2Player("L\214nh B\181i Chi\213n Tr\173\234ng Th\173\172ng Chu: l\199n d\239ng ti\213p theo sau 60 ph\243t.")
end

function PTTC_Shang() PTTC_Go(1) end
function PTTC_Zhou() PTTC_Go(2) end

-- back into the round the player already joined (left the map): same side, free, no cooldown
function PTTC_Back()
	PTTC_Load()
	if not PTTC_SrcOk() then PTTC_Blocked() return end
	if not PTVC_InRound() then PTTC_Main() return end
	if not PTTC_MapOk() then return end
	if not PTVC_Enter(GetTask(PTVC_T_SIDE)) then
		Msg2Player("Chi\213n tr\173\234ng \174\183 \174\241 ng\173\234i, h\183y \174\238i tr\203n sau.")
	end
end

function main(nItemIdx)
	PTTC_Main()
	return 0
end
